"""Renderiza revisão interna com Brand Atlas local, fontes e arte incorporadas."""
import base64, html, json, re, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
folder=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'library/revisao-bordoes-bruno-2026-10-24'
data=json.loads((folder/'alteracoes.json').read_text())
assets=ROOT/'docs/brand/site/dist/assets'
def uri(name,mime):return 'data:'+mime+';base64,'+base64.b64encode((assets/name).read_bytes()).decode()
fonts=(assets/'fonts.css').read_text()
fonts=re.sub(r'url\((font-\d\.woff2)\)',lambda m:'url('+uri(m[1],'font/woff2')+')',fonts)
esc=html.escape
refs=list(dict.fromkeys(c['ref'] for c in data['changes']))
nav=''.join(f'<a href="#{r}">{r}</a>' for r in refs)
sections=[]
for r in refs:
 cards=[]
 for c in data['changes']:
  if c['ref']!=r:continue
  new=esc(c['depois'])
  for phrase in ['Chupa-Cabra!','Tá, Amor?']:new=new.replace(phrase,'<mark>'+phrase+'</mark>')
  duration=f"{c['duracao_sugerida']}s sugeridos"
  cards.append(f'<article><div class="shot"><span>{c["shot"]}</span><span>{duration}</span></div><div class="comparison"><div class="before"><span class="label">Fala original</span><p>{esc(c["antes"])}</p></div><div class="after"><span class="label">Com a voz do Bruno</span><p>{new}</p></div></div></article>')
 sections.append(f'<section id="{r}" class="reference"><header class="sectionhead"><span class="label">Referência / {r[-4:]}</span><h2>{r}</h2><span class="count">{len(cards):02d} ajuste'+('s' if len(cards)>1 else '')+'</span></header>'+''.join(cards)+'</section>')
css='''
:root{color-scheme:dark;--ink:#000;--paper:#fff;--accent:#ee794e;--muted:#a3a3a3;--line:#2c2c2c}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--ink);color:var(--paper);font-family:'DM Sans',sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,a{touch-action:manipulation}a:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.wrap{max-width:1120px;margin:auto;padding:0 48px}.masthead{height:112px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.signature{width:164px;height:70px;object-fit:contain}.label,.edition,.shot,.count,.nav a,.status,footer{font:400 12px/1.5 'DM Mono',monospace;letter-spacing:.06em}.edition{text-align:right;color:var(--muted)}.hero{position:relative;isolation:isolate;text-align:center;padding:96px 0 72px;overflow:hidden}.art{position:absolute;width:620px;height:470px;object-fit:contain;right:-180px;top:0;opacity:.32;mask-image:radial-gradient(ellipse at center,#000 0%,rgba(0,0,0,.7) 35%,transparent 70%);z-index:-1;pointer-events:none}.hero .label{color:var(--accent)}h1{font-size:clamp(52px,6.5vw,88px);font-weight:300;line-height:1.02;letter-spacing:-.04em;margin:24px 0;text-wrap:balance}h1 em{font-family:'DM Serif Display',serif;font-weight:400}.intro{font-size:18px;line-height:1.6;max-width:570px;margin:24px auto 32px;color:#c4c4c4;text-wrap:pretty}.status{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:10px 18px}.status:before{content:'●';color:var(--accent);margin-right:10px}.stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:28px 0}.stat{text-align:center;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat strong{display:block;font-weight:300;font-size:40px;line-height:1.2}.stat span{color:var(--muted);font-size:14px}.nav{position:sticky;top:0;z-index:4;background:#000f;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;padding:16px 0;overflow-x:auto;backdrop-filter:blur(12px)}.nav>span{color:var(--muted);margin-right:16px;white-space:nowrap}.nav a{padding:8px 12px;border:1px solid var(--line);border-radius:999px;transition:background .18s,color .18s}.nav a:hover{background:var(--accent);color:#000;border-color:var(--accent)}.voice{display:grid;grid-template-columns:1fr 2fr;gap:48px;padding:64px 0;border-bottom:1px solid var(--line)}.voice h2{font:italic 40px/1.08 'DM Serif Display',serif;margin:14px 0}.voice p{font-size:16px;line-height:1.7;color:#c4c4c4;margin:0}.tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}.tags span{font-size:14px;border:1px solid var(--line);padding:6px 12px;border-radius:999px}.reference{padding:64px 0 0}.sectionhead{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:24px}.sectionhead>.label{flex-basis:100%;color:var(--accent)}h2{font-size:28px;font-weight:400;letter-spacing:-.035em;margin:0}.count{margin-left:auto;color:var(--muted)}article{border-top:1px solid var(--line);padding:24px 0 32px}.shot{display:flex;justify-content:space-between;color:var(--muted);margin-bottom:24px}.shot span:first-child{color:var(--paper)}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:48px}.comparison p{font-size:19px;line-height:1.65;margin:12px 0 0;text-wrap:pretty}.comparison .label{color:var(--muted)}.before p{color:var(--muted)}.after{border-left:1px solid var(--line);padding-left:32px}.after .label{color:var(--accent)}mark{color:#000;background:var(--accent);padding:0 4px;box-decoration-break:clone;-webkit-box-decoration-break:clone}footer{display:flex;justify-content:space-between;gap:24px;border-top:1px solid var(--line);margin-top:64px;padding:32px 0 48px;color:var(--muted)}@media(max-width:700px){.wrap{padding:0 24px}.masthead{height:96px}.signature{width:160px}.edition{font-size:10px}.hero{padding:64px 0 48px}.art{right:-300px;opacity:.32}h1{font-size:54px}.intro{font-size:16px}.stats{padding:24px 0}.stat strong{font-size:32px}.stat span{font-size:12px}.nav{gap:6px}.nav>span{display:none}.voice{grid-template-columns:1fr;gap:24px;padding:48px 0}.voice h2{font-size:36px}.comparison{grid-template-columns:1fr;gap:24px}.after{border-left:2px solid var(--accent);padding-left:20px}.comparison p{font-size:18px}.reference{padding-top:48px}h2{font-size:24px}.count{font-size:10px}footer{flex-direction:column}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}@media print{.nav,.art{display:none}.wrap{padding:0 24px}.hero{padding:32px 0}.reference{break-inside:avoid}.comparison{grid-template-columns:1fr 1fr}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''
page=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bruno · Revisão de bordões — Matheus Marcolino</title><style>{fonts}{css}</style></head><body><div class="wrap"><header class="masthead"><img class="signature" src="{uri('assinatura-branca.svg','image/svg+xml')}" alt="Matheus Marcolino"><div class="edition">ESTÚDIO / CONTEÚDO<br>24 OUT 2026 · REVISÃO 01</div></header><main><section class="hero"><img class="art" src="{uri('refracao-768.webp','image/webp')}" alt=""><span class="label">Bruno Goytacaz / Direção de voz</span><h1>O jeito dele.<br><em>Em cada fala.</em></h1><p class="intro">Acréscimos pontuais para trazer os bordões do Bruno aos roteiros. Compare cada ajuste e revise antes da próxima geração.</p><span class="status">Aguardando sua revisão</span></section><div class="stats"><div class="stat"><strong>{len(refs):02d}</strong><span>referências revisadas</span></div><div class="stat"><strong>{len(data['changes']):02d}</strong><span>falas com acréscimos</span></div><div class="stat"><strong>121</strong><span>shots na ordem original</span></div></div><nav class="nav" aria-label="Referências"><span class="label">IR PARA</span>{nav}</nav><section class="voice"><div><span class="label">01 / Interpretação</span><h2>Presença na voz.</h2><div class="tags"><span>Chupa-Cabra</span><span>Tá, Amor?</span></div></div><p>{esc(data['direction'])}</p></section>{''.join(sections)}</main><footer><span>MATHEUS MARCOLINO / BRUNO GOYTACAZ</span><span>Revisão interna · Nenhuma geração nova<br>Original preservado · Bordões em destaque</span><a href="#">Voltar ao início ↑</a></footer></div></body></html>'''
(folder/'revisao.html').write_text(page)
print(str(folder/'revisao.html'))
